import{_ as r,o as a,c as t,a5 as i}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"参考文献・参考リソース","description":"","frontmatter":{"title":"参考文献・参考リソース","study":{"source":"C++ Wiki","kind":"参考資料","status":"既存原稿","summary":"このWikiの内容をより深く学ぶための資料です。書籍は版を問わず定番のものを挙げています。 Robert C. Martin『Clean Architecture 達人に学ぶソフトウェアの構造と設計』 — SOLID原則の一次情報に近い解説。「変更理由」の観点はここから。"}},"headers":[],"relativePath":"guide/cpp-references.md","filePath":"guide/cpp-references.md"}'),l={name:"guide/cpp-references.md"};function n(o,e,c,s,h,d){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="参考文献・参考リソース" tabindex="-1">参考文献・参考リソース <a class="header-anchor" href="#参考文献・参考リソース" aria-label="Permalink to &quot;参考文献・参考リソース&quot;">​</a></h1><p>このWikiの内容をより深く学ぶための資料です。書籍は版を問わず定番のものを挙げています。</p><h2 id="設計・オブジェクト指向" tabindex="-1">設計・オブジェクト指向 <a class="header-anchor" href="#設計・オブジェクト指向" aria-label="Permalink to &quot;設計・オブジェクト指向&quot;">​</a></h2><ul><li>Robert C. Martin『Clean Architecture 達人に学ぶソフトウェアの構造と設計』 — SOLID原則の一次情報に近い解説。「変更理由」の観点はここから。</li><li>Erich Gamma ほか『オブジェクト指向における再利用のためのデザインパターン』(いわゆるGoF本) — 23パターンの原典。例が古い(GUIフレームワーク中心)ので、本Wikiではゲーム向けに置き換えて説明している。</li><li>Martin Fowler『リファクタリング(第2版)』 — コードの臭いカタログとリファクタリング手順の定番。</li><li>Kent Beck『テスト駆動開発』 — テスト容易性を設計の駆動力にする考え方。</li><li>上田勲『プリンシプル オブ プログラミング』 — YAGNI/KISS/DRYなど原則の横断的整理。</li></ul><h2 id="ゲームプログラミング" tabindex="-1">ゲームプログラミング <a class="header-anchor" href="#ゲームプログラミング" aria-label="Permalink to &quot;ゲームプログラミング&quot;">​</a></h2><ul><li>Robert Nystrom『Game Programming Patterns』(邦訳: ゲームプログラミングパターン) — 第4部の主要な出典。Web版が無料公開されている: <a href="https://gameprogrammingpatterns.com/" target="_blank" rel="noreferrer">https://gameprogrammingpatterns.com/</a></li><li>Jason Gregory『ゲームエンジンアーキテクチャ』 — エンジン全体の構造、メモリ管理、ゲームループの実務的な詳細。</li><li>Mike Acton の Data-Oriented Design 講演 (CppCon 2014 &quot;Data-Oriented Design and C++&quot;) — Data Locality / AoS-SoA の背景思想。</li></ul><h2 id="c" tabindex="-1">C++ <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C++&quot;">​</a></h2><ul><li>Bjarne Stroustrup『プログラミング言語C++』 — 言語設計者による網羅的解説。</li><li>Scott Meyers『Effective Modern C++』 — ムーブ、auto、スマートポインタなどC++11/14の要点。</li><li>cppreference.com ( <a href="https://ja.cppreference.com/" target="_blank" rel="noreferrer">https://ja.cppreference.com/</a> ) — 標準ライブラリと言語仕様の事実上の標準リファレンス。本Wikiの言語仕様の記述はここで確認できる。</li><li>ISO C++ 規格ドラフト ( <a href="https://eel.is/c++draft/" target="_blank" rel="noreferrer">https://eel.is/c++draft/</a> ) — 「標準で保証されること」の一次情報。</li><li>Compiler Explorer ( <a href="https://godbolt.org/" target="_blank" rel="noreferrer">https://godbolt.org/</a> ) — コードがどんなアセンブリになるかをブラウザで確認できる。第6部を読むときに強く推奨。</li><li>CppCon / Meeting C++ の講演動画 — 実装の内部やパフォーマンスの一次情報が多い。</li></ul><h2 id="ビルド・ツールチェーン" tabindex="-1">ビルド・ツールチェーン <a class="header-anchor" href="#ビルド・ツールチェーン" aria-label="Permalink to &quot;ビルド・ツールチェーン&quot;">​</a></h2><ul><li>CMake 公式ドキュメント ( <a href="https://cmake.org/documentation/" target="_blank" rel="noreferrer">https://cmake.org/documentation/</a> )</li><li>各コンパイラのドキュメント: MSVC ( <a href="https://learn.microsoft.com/cpp/" target="_blank" rel="noreferrer">https://learn.microsoft.com/cpp/</a> ) / Clang ( <a href="https://clang.llvm.org/docs/" target="_blank" rel="noreferrer">https://clang.llvm.org/docs/</a> ) / GCC ( <a href="https://gcc.gnu.org/onlinedocs/" target="_blank" rel="noreferrer">https://gcc.gnu.org/onlinedocs/</a> )</li><li>Peter Smith『Linkers and Loaders』(John R. Levine著の同名書も定番) — リンクとローダーの古典。</li></ul><h2 id="unity-c" tabindex="-1">Unity / C# <a class="header-anchor" href="#unity-c" aria-label="Permalink to &quot;Unity / C#&quot;">​</a></h2><ul><li>Unity 公式マニュアルとスクリプティングリファレンス ( <a href="https://docs.unity3d.com/" target="_blank" rel="noreferrer">https://docs.unity3d.com/</a> )</li><li>Unity 公式: IL2CPP のドキュメント — C++変換の仕組み。</li><li>Jon Skeet『C# in Depth』 — C#言語仕様の深掘り。</li><li>.NET のGC設計ドキュメント ( <a href="https://learn.microsoft.com/dotnet/standard/garbage-collection/" target="_blank" rel="noreferrer">https://learn.microsoft.com/dotnet/standard/garbage-collection/</a> )</li></ul><h2 id="unreal-engine" tabindex="-1">Unreal Engine <a class="header-anchor" href="#unreal-engine" aria-label="Permalink to &quot;Unreal Engine&quot;">​</a></h2><ul><li>Unreal Engine 公式ドキュメント ( <a href="https://dev.epicgames.com/documentation/" target="_blank" rel="noreferrer">https://dev.epicgames.com/documentation/</a> )</li><li>公式ソースコード(GitHub、Epicアカウント連携で閲覧可) — UEの仕様の最終的な一次情報はソースコード。</li><li>「Unreal Engine 5で極めるゲーム開発」(歴代の定番入門書のいずれか) — Gameplay Framework の全体像。</li></ul><h2 id="本wikiでの引用・準拠方針" tabindex="-1">本Wikiでの引用・準拠方針 <a class="header-anchor" href="#本wikiでの引用・準拠方針" aria-label="Permalink to &quot;本Wikiでの引用・準拠方針&quot;">​</a></h2><ul><li>言語仕様に関する記述は C++20 (ISO/IEC 14882:2020) を基準にし、処理系依存の事項はその旨を明記している。</li><li>Unity / Unreal Engine の仕様はバージョンによって変わるため、本Wikiでは特定バージョンに依存しない範囲で説明し、依存する場合は本文中に注記している。</li></ul><hr><p><a href="/study/guide/cpp-index.html">目次に戻る</a></p>',18)])])}const m=r(l,[["render",n]]);export{u as __pageData,m as default};
